/**
 * Emit plain `.js` next to every `.ts` source.
 *
 * Node 24 runs the TypeScript sources directly (type stripping), so the `.ts` files are
 * the source of truth. The generated `.js` files exist so that consumers who import with
 * `.js` specifiers — or who run on a toolchain without TypeScript support — get the same
 * library. Run `node scripts/build-js.mjs` after changing anything under `src/`.
 */
import { readdir, readFile, writeFile } from "node:fs/promises";
import { stripTypeScriptTypes } from "node:module";
import path from "node:path";
import { fileURLToPath } from "node:url";

const SRC = fileURLToPath(new URL("../src", import.meta.url));

const walk = async (dir) => {
  const entries = await readdir(dir, { withFileTypes: true });
  const files = [];
  for (const entry of entries) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      files.push(...(await walk(full)));
    } else if (entry.name.endsWith(".ts") && !entry.name.endsWith(".d.ts")) {
      files.push(full);
    }
  }
  return files;
};

const files = await walk(SRC);
for (const file of files) {
  const source = await readFile(file, "utf8");
  const stripped = stripTypeScriptTypes(source, { mode: "strip" });
  // relative specifiers point at `.ts`; the emitted JS must point at the emitted JS.
  const rewritten = stripped.replace(
    /(from\s*["'])(\.\.?\/[^"']+)\.ts(["'])/g,
    "$1$2.js$3",
  );
  const out = `${file.slice(0, -3)}.js`;
  await writeFile(out, rewritten);
  console.log(`wrote ${path.relative(path.dirname(SRC), out)}`);
}

