/**
 * The `.js` files under src/ are generated from the `.ts` sources by scripts/build-js.mjs.
 * This test makes sure the generated build is present and behaves like the TypeScript one.
 */
import assert from "node:assert/strict";
import { describe, it } from "node:test";

import * as ts from "../src/index.ts";
// @ts-expect-error - the generated JS build has no type declarations of its own.
import * as js from "../src/index.js";

describe("generated JS build", () => {
  it("exports the same names as the TypeScript sources", () => {
    assert.deepEqual(Object.keys(js).sort(), Object.keys(ts).sort());
  });

  it("parses grammars identically", () => {
    const grammar = 'root ::= "foo" | [a-z]+';
    const fromJs = [...js.GBNF(grammar).add("f")].map((rule: unknown) =>
      JSON.stringify(rule),
    );
    const fromTs = [...ts.GBNF(grammar).add("f")].map((rule) => JSON.stringify(rule));
    assert.deepEqual(fromJs.sort(), fromTs.sort());
  });

  it("throws the same errors", () => {
    assert.throws(() => js.GBNF("root ::= foo"), { message: /Undefined rule identifier/ });
  });
});

